import sys, json, threading, http.server, functools, importlib.util
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[2]; OUT=Path('/tmp/prime-demo-browser-validation');OUT.mkdir(exist_ok=True)
handler=functools.partial(http.server.SimpleHTTPRequestHandler,directory=str(ROOT))
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),handler)
threading.Thread(target=server.serve_forever,daemon=True).start()
base=__import__('os').environ.get('PRIME_DEMO_BASE_URL',f'http://127.0.0.1:{server.server_port}').rstrip('/')
spec=importlib.util.spec_from_file_location('core', ROOT/'prime/aee_logodecrypt_prime.py');core=importlib.util.module_from_spec(spec);spec.loader.exec_module(core)
checks=[]
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True)
 page=browser.new_page(viewport={'width':1440,'height':1000},device_scale_factor=1)
 errors=[];requests=[]
 page.on('pageerror',lambda e:errors.append(str(e)))
 page.on('request',lambda r:requests.append({'url':r.url,'method':r.method}))
 page.goto(base+'/prime/demo-environment/lab.html')
 page.wait_for_function("document.querySelectorAll('#missions button').length===3")
 page.screenshot(path=str(OUT/'prime-decision-room-desktop.png'),full_page=True)
 assert page.locator('#fixture option').count()==12;checks.append('11 fixtures + custom option')
 page.locator('#hold').click();assert page.locator('#cascade .cascade-step').count()==4;checks.append('hold intervention path')
 page.locator('[data-path=release]').click();assert page.locator('#cascade').inner_text().find('rent day')>=0;checks.append('scenario-specific unchecked cascade')
 page.locator('#missions button').nth(2).click();page.locator('#release').click();assert 'roles switched' in page.locator('#decision-heading').inner_text();checks.append('guided blind spot disclosed')
 page.locator('#analyze').click()
 page.wait_for_function("!document.querySelector('#analysis-output').hidden || document.querySelector('#analysis-status').textContent.includes('unavailable')",timeout=120000)
 print('ENGINE STATUS',page.locator('#runtime-status').inner_text())
 assert not page.locator('#analysis-output').get_attribute('hidden'),page.locator('#analysis-status').inner_text()
 checks.append('real browser runtime initializes and core self-tests pass')
 cases=json.loads((ROOT/'prime/demo-environment/scenarios.json').read_text())
 for c in cases:
  page.locator('#fixture').select_option(c['id']);page.locator('#analyze').click()
  page.wait_for_function("!document.querySelector('#analysis-output').hidden",timeout=15000)
  actual=json.loads(page.locator('#json-output').text_content())
  expected=core.analyze(c['candidate'],c['source'],c['frame'],12)
  
  if actual!=expected:
   (OUT/'actual.json').write_text(json.dumps(actual,indent=2));(OUT/'expected.json').write_text(json.dumps(expected,indent=2))
   raise AssertionError((c['id'],'browser differs from Python'))
  assert core.verify(actual);checks.append('browser = Python, receipt verified: '+c['id'])
 page.locator('#source').fill('Order 37: 12 records failed.');page.locator('#candidate').fill('Order 37: 14 records passed.');page.locator('#analyze').click();page.wait_for_function("!document.querySelector('#analysis-output').hidden")
 actual=json.loads(page.locator('#json-output').text_content());assert actual==core.analyze('Order 37: 14 records passed.','Order 37: 12 records failed.','general',12);checks.append('custom pair recomputes exact result')
 with page.expect_download() as d:page.locator('#download-json').click()
 d.value.save_as(str(OUT/'sample-analysis.json'));assert json.loads((OUT/'sample-analysis.json').read_text())==actual;checks.append('JSON download preserves exact result')
 with page.expect_download() as d:page.locator('#download-report').click()
 d.value.save_as(str(OUT/'sample-review-brief.md'));assert 'Order 37: 12 records failed.' in (OUT/'sample-review-brief.md').read_text();checks.append('review brief preserves paired source')
 with page.expect_download() as d:page.locator('#download-pilot').click()
 d.value.save_as(str(OUT/'PRIME-collaboration-kit.md'));checks.append('collaboration kit downloads')
 page.locator('#use-source').uncheck();page.locator('#analyze').click();page.wait_for_function("!document.querySelector('#analysis-output').hidden")
 assert json.loads(page.locator('#json-output').text_content())['context_fidelity']['status']=='NOT-RUN';assert 'No source comparison' in page.locator('#changes').inner_text();checks.append('source comparison off state')
 page.locator('#candidate').fill('<script>alert("no")</script>');assert page.locator('#analysis-output').is_hidden();checks.append('edited inputs hide stale result')
 page.locator('#analyze').click();page.wait_for_function("!document.querySelector('#analysis-output').hidden");assert json.loads(page.locator('#json-output').text_content())['source_verbatim']=='<script>alert("no")</script>';checks.append('HTML input stays inert exact text')
 page.locator('#clear').click();page.locator('#analyze').click();page.wait_for_function("!document.querySelector('#analysis-output').hidden");assert json.loads(page.locator('#json-output').text_content())['source_verbatim']=='';checks.append('empty input supported')
 page.locator('#fixture').select_option('unicode-boundary');page.locator('#analyze').click();page.wait_for_function("!document.querySelector('#analysis-output').hidden");page.locator('#analysis-output').scroll_into_view_if_needed();page.screenshot(path=str(OUT/'prime-live-results-desktop.png'))
 assert not errors,errors;assert all(x['url'].startswith(base) for x in requests),requests;assert all(x['method']=='GET' for x in requests);checks.append('no page errors, no text uploads or third-party requests during exercised flows')
 mobile=browser.new_page(viewport={'width':390,'height':844},device_scale_factor=1,is_mobile=True,has_touch=True)
 mobile.goto(base+'/prime/demo-environment/lab.html');mobile.wait_for_function("document.querySelectorAll('#missions button').length===3")
 assert mobile.evaluate('document.documentElement.scrollWidth<=window.innerWidth');checks.append('390px mobile has no horizontal overflow')
 mobile.screenshot(path=str(OUT/'prime-decision-room-mobile.png'),full_page=True)
 mobile.locator('#analyze').click();mobile.wait_for_function("!document.querySelector('#analysis-output').hidden",timeout=120000);assert 'verified' in mobile.locator('#result-banner').inner_text();checks.append('mobile real Python engine and receipt verify');
 mobile.locator('#missions button').nth(1).click();mobile.locator('#hold').click();assert mobile.locator('#cascade .cascade-step').count()==4;checks.append('mobile guided flow works')
 browser.close()
server.shutdown()
report={'checks_passed':len(checks),'checks':checks,'engine_self_tests':core.self_test()['passed'],'browser':'Chromium 145 via Playwright 1.58.0','scope':'Implementation and browser parity tests, not independent semantic accuracy or persuasion/outcome measurement','page_errors':errors,'requests':requests}
(OUT/'browser-validation.json').write_text(json.dumps(report,indent=2))
print(json.dumps({k:v for k,v in report.items() if k!='requests'},indent=2))
